import { _decorator, Component, Node, Vec3, Color } from 'cc';
import { Enemy, EnemyArchetype, EnemyArchetypes, EnemyKind } from './Enemy';
import { buildHumanoid } from '../core/CharacterBuilder';
import { createPrimitiveNode, Palette } from '../core/PrimitiveFactory';
import { PlayerStats } from '../player/PlayerStats';
import { Inventory } from '../inventory/Inventory';
const { ccclass } = _decorator;

// Spawns enemies evenly distributed in zones around the map
@ccclass('EnemySpawner')
export class EnemySpawner extends Component {
    public worldRoot: Node | null = null;
    public player: Node | null = null;
    public playerStats: PlayerStats | null = null;
    public inventory: Inventory | null = null;
    public enemies: Enemy[] = [];

    // Zone definitions: position center, radius, allowed kinds, count
    private zones: { center: Vec3, radius: number, kinds: EnemyKind[], count: number }[] = [
        { center: new Vec3(-40, 0, -40), radius: 18, kinds: ['goblin'], count: 6 },
        { center: new Vec3( 40, 0, -40), radius: 18, kinds: ['wolf'], count: 5 },
        { center: new Vec3(-40, 0,  40), radius: 18, kinds: ['skeleton'], count: 6 },
        { center: new Vec3( 40, 0,  40), radius: 18, kinds: ['orc'], count: 4 },
        { center: new Vec3(  0, 0, -65), radius: 12, kinds: ['goblin', 'wolf'], count: 5 },
        { center: new Vec3(  0, 0,  65), radius: 12, kinds: ['skeleton', 'orc'], count: 5 },
        { center: new Vec3(-65, 0,   0), radius: 12, kinds: ['wolf', 'goblin'], count: 5 },
        { center: new Vec3( 65, 0,   0), radius: 12, kinds: ['orc', 'skeleton'], count: 4 },
        // Boss spawn (single)
        { center: new Vec3( 0, 0, -85), radius: 4,  kinds: ['boss'], count: 1 },
    ];

    spawnAll() {
        if (!this.worldRoot || !this.player || !this.playerStats || !this.inventory) return;
        for (const zone of this.zones) {
            for (let i = 0; i < zone.count; i++) {
                const kind = zone.kinds[Math.floor(Math.random() * zone.kinds.length)];
                const ang = Math.random() * Math.PI * 2;
                const r = Math.random() * zone.radius;
                const x = zone.center.x + Math.cos(ang) * r;
                const z = zone.center.z + Math.sin(ang) * r;
                this.spawn(kind, new Vec3(x, 0, z));
            }
        }
    }

    spawn(kind: EnemyKind, pos: Vec3): Enemy | null {
        const arch = EnemyArchetypes[kind];
        if (!arch) return null;
        const node = this.buildVisual(kind, arch);
        node.setPosition(pos);
        this.worldRoot!.addChild(node);

        const en = node.addComponent(Enemy);
        en.init(arch, this.player!, this.playerStats!, this.inventory!);

        // Find body parts for animation
        const lArm = node.getChildByName('LeftArm') ?? undefined;
        const rArm = node.getChildByName('RightArm') ?? undefined;
        const lLeg = node.getChildByName('LeftLeg') ?? undefined;
        const rLeg = node.getChildByName('RightLeg') ?? undefined;
        const body = node.getChildByName('Body') ?? undefined;
        if (lArm && rArm) en.setBodyRefs({ l: lArm, r: rArm, lLeg, rLeg, body });

        this.enemies.push(en);
        return en;
    }

    private buildVisual(kind: EnemyKind, arch: EnemyArchetype): Node {
        if (kind === 'wolf') {
            // Quadruped: low body + 4 legs + head
            const root = new Node('Wolf');
            const body = createPrimitiveNode('Body', 'box', new Vec3(1.4, 0.5, 0.6), arch.color);
            body.setPosition(0, 0.7, 0);
            root.addChild(body);
            const head = createPrimitiveNode('Head', 'box', new Vec3(0.5, 0.5, 0.5), arch.color);
            head.setPosition(0.7, 0.9, 0);
            root.addChild(head);
            const tail = createPrimitiveNode('Tail', 'box', new Vec3(0.5, 0.15, 0.15), arch.color);
            tail.setPosition(-0.8, 0.8, 0);
            root.addChild(tail);
            // legs
            const lA = createPrimitiveNode('LeftArm', 'box', new Vec3(0.18, 0.5, 0.18), arch.color);
            lA.setPosition(0.5, 0.25, 0.25); root.addChild(lA);
            const rA = createPrimitiveNode('RightArm', 'box', new Vec3(0.18, 0.5, 0.18), arch.color);
            rA.setPosition(0.5, 0.25, -0.25); root.addChild(rA);
            const lL = createPrimitiveNode('LeftLeg', 'box', new Vec3(0.18, 0.5, 0.18), arch.color);
            lL.setPosition(-0.5, 0.25, 0.25); root.addChild(lL);
            const rL = createPrimitiveNode('RightLeg', 'box', new Vec3(0.18, 0.5, 0.18), arch.color);
            rL.setPosition(-0.5, 0.25, -0.25); root.addChild(rL);
            return root;
        }

        // Humanoid variants
        let colors: any = {};
        let scale = arch.scale;
        if (kind === 'goblin') colors = { skin: arch.color, shirt: Palette.leather, pants: Palette.woodDark, hair: new Color(40, 30, 20) };
        else if (kind === 'skeleton') colors = { skin: arch.color, shirt: new Color(80, 80, 90), pants: new Color(80, 80, 90), hair: new Color(200, 200, 200) };
        else if (kind === 'orc') colors = { skin: arch.color, shirt: Palette.leather, pants: Palette.woodDark, hair: new Color(30, 25, 15) };
        else if (kind === 'boss') colors = { skin: arch.color, shirt: new Color(40, 35, 50), pants: new Color(30, 25, 40), hair: new Color(160, 30, 30) };

        const parts = buildHumanoid(arch.name, colors, scale);

        // Weapon visual
        if (kind === 'orc' || kind === 'skeleton' || kind === 'boss') {
            const sword = createPrimitiveNode('Weapon', 'box', new Vec3(0.12, 1.2, 0.12), Palette.iron);
            sword.setPosition(0, -0.6, 0);
            parts.weaponSlot.addChild(sword);
        }
        if (kind === 'boss') {
            // crown
            const crown = createPrimitiveNode('Crown', 'cylinder', new Vec3(0.7, 0.2, 0.7), Palette.gold);
            crown.setPosition(0, 2.45 * scale, 0);
            parts.root.addChild(crown);
        }
        return parts.root;
    }
}